import React, { useState, useEffect } from "react";
import TaskList from "./components/TaskList";
import { Line } from "react-chartjs-2";
import { Chart as ChartJS } from "chart.js/auto";
import { PlusCircle } from "lucide-react";
import { DndProvider, useDrag, useDrop } from "react-dnd";
import { HTML5Backend } from "react-dnd-html5-backend";
import "./App.css";

function App() {
  const [tasks, setTasks] = useState([]);
  const [taskInputs, setTaskInputs] = useState({ 1: "", 2: "", 3: "", 4: "" });
  const [reminders, setReminders] = useState({});

  const addTask = (quadrant) => {
    if (!taskInputs[quadrant].trim()) return;
    const newTask = {
      id: Date.now(),
      text: taskInputs[quadrant],
      quadrant,
      timer: 0,
      completed: false,
      dueDate: null,
    };
    setTasks([...tasks, newTask]);
    setTaskInputs({ ...taskInputs, [quadrant]: "" });
  };

  const moveTask = (taskId, newQuadrant) => {
    setTasks(tasks.map(task => task.id === taskId ? { ...task, quadrant: newQuadrant } : task));
  };

  const setTaskDueDate = (taskId, dueDate) => {
    setTasks(tasks.map(task => task.id === taskId ? { ...task, dueDate } : task));
  };

  const chartData = {
    labels: tasks.map((t) => t.text),
    datasets: [
      {
        label: "Task Duration (seconds)",
        data: tasks.map((t) => t.timer),
        borderColor: "rgba(75, 192, 192, 1)",
        backgroundColor: "rgba(75, 192, 192, 0.2)",
        borderWidth: 1,
      },
    ],
  };

  return (
    <DndProvider backend={HTML5Backend}>
      <div className="App">
        <h1>Eisenhower Matrix</h1>
        <table className="matrix-table">
          <tbody>
            {[ [1, 2], [3, 4] ].map((row, rowIndex) => (
              <tr key={rowIndex}>
                {row.map((quadrant) => (
                  <Quadrant key={quadrant} quadrant={quadrant} tasks={tasks} addTask={addTask} moveTask={moveTask} setTaskDueDate={setTaskDueDate} />
                ))}
              </tr>
            ))}
          </tbody>
        </table>
        <Line data={chartData} />
      </div>
    </DndProvider>
  );
}

function Quadrant({ quadrant, tasks, addTask, moveTask, setTaskDueDate }) {
  const [{ isOver }, drop] = useDrop(() => ({
    accept: "TASK",
    drop: (item) => moveTask(item.id, quadrant),
    collect: (monitor) => ({ isOver: !!monitor.isOver() }),
  }));

  return (
    <td ref={drop} className={`quadrant ${isOver ? "highlight" : ""}`}>
      <h2>{["Important & Urgent", "Important & Not Urgent", "Not Important & Urgent", "Not Important & Not Urgent"][quadrant - 1]}</h2>
      <div className="task-input">
        <input type="text" placeholder="Enter Task" onKeyDown={(e) => e.key === "Enter" && addTask(quadrant)} />
        <PlusCircle className="add-icon" onClick={() => addTask(quadrant)} />
      </div>
      <TaskList quadrant={quadrant} tasks={tasks} setTaskDueDate={setTaskDueDate} />
    </td>
  );
}

export default App;
